export const emptyWorkspace=()=>({version:2,dataMode:'real',theme:'light',users:[],accounts:[],trades:[],entries:[],importBatches:[],deletedManualTrades:[],activity:[],userSettings:{},profile:{name:'',email:'',timezone:'UTC',currency:'USD'},risk:{perTrade:1,dailyLoss:3,maxTrades:3},preferences:{email:false,sync:true,weekly:false}});
export class APIError extends Error{constructor(status,message){super(message);this.status=status;}}
export async function request(path,options={}){let response;try{response=await fetch(path,{credentials:'same-origin',...options,headers:options.body instanceof FormData?options.headers:{'Content-Type':'application/json',...options.headers}});}catch{throw new APIError(0,'Could not reach your cloud journal. Check your connection and retry.');}let result;try{result=await response.json();}catch{throw new APIError(response.status,'The journal backend is unavailable. Please retry shortly.');}if(!response.ok)throw new APIError(response.status,result.error||'This action could not be completed.');return result;}
export const operation=(type,fields={},extra={})=>request('/api/action',{method:'POST',body:JSON.stringify({type,fields,...extra})});
export async function uploadReport(file,options){const form=new FormData();form.set('file',file);form.set('options',JSON.stringify(options));return request('/api/imports',{method:'POST',body:form});}
